func TestCases(t *testing.T) {
	for _, tc := range []struct {
		testName string
		want     int
	}{
		{testName: "first-case", want: 1},
		{testName: "second_case", want: 2},
		{testName: "has space", want: 3},
		{testName: dynamicName, want: 4},
	} {
		_ = tc
	}
}

func TestDuplicateCase(t *testing.T) {
	names := []string{}
	_ = names
	x := struct{ name string }{name: "dup"}
	y := struct{ name string }{name: "dup"}
	_, _ = x, y
}

func TestSemicolonsOnly(t *testing.T) { ; ; }

